import { OverlayModule } from "../overlay_module.js";

export class FishBalanceOverlayModule extends OverlayModule {
  #liveForceSection;
  #forcePreviewSection;

  constructor(options = {}) {
    super("fishBalance", options);
    this.#liveForceSection = options.liveForceSection;
    this.#forcePreviewSection = options.forcePreviewSection;
  }

  shouldRender(data) {
    return (
      data.gameState === "playing" &&
      (
        this.#liveForceSection.hasData(data) ||
        this.#forcePreviewSection.hasStates(data)
      )
    );
  }

  render(data) {
    let html = this.formatHeader("FISH BALANCE", "#ffaa00");
    html += this.#liveForceSection.render(data, this);
    if (this.#forcePreviewSection.hasStates(data)) {
      html += this.#forcePreviewSection.render(data, {
        includeHeader: true,
        headerTitle: "STATE FORCE PREVIEW",
      });
    }
    return html + `<div class="debug-overlay__spacer"></div>`;
  }
}
